        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1:
            line_colors.append(col[0])
    sep = max(set(line_colors), key=line_colors.count)

    row_seps = [r for r in range(h) if all(x == sep for x in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    def blocks(size, cuts):
        result = []
        start = 0
        for cut in cuts:
            if start < cut:
                result.append((start, cut))
            start = cut + 1
        if start < size:
            result.append((start, size))
        return result

    rows = blocks(h, row_seps)
    cols = blocks(w, col_seps)

    colors = [x for row in grid for x in row if x != sep]
    background = max(set(colors), key=colors.count)
    marker = next(x for x in set(colors) if x != background)

    out = []
    for r0, r1 in rows:
        out_row = []
        for c0, c1 in cols:
            count = sum(grid[r][c] == marker
                        for r in range(r0, r1)
                        for c in range(c0, c1))
            out_row.append(1 if count == 2 else background)
        out.append(out_row)
    return out
